 source=H/'source_geography_inclusive_v2';pre=source/'source_mass_preflight';base=H/'access_v2_bound/config_baseline_provisional.json';out=H/'access_v2_seventh_bound';assert not out.exists()
 review=ROOT/'reviews/cycle06/network2021_seventh_transport_combined_independent_admission.json';rj=json.loads(review.read_text());assert rj['all_checks_passed'] is True and rj['first6_scope_preserved'] is True and rj['combined_destinations']==17913
 sr=ROOT/'reviews/cycle06/source_geography_v2_preregistration_independent_admission.json';assert json.loads(sr.read_text())['all_checks_passed'] is True and sha(source/'preregistration.json') in sr.read_text()
