 for frame,manifest in [(source,source/'freeze_manifest.json'),(pre,pre/'freeze_manifest.json'),(H/'access_v2_bound',H/'access_v2_bound/freeze_manifest.json')]:
  f=json.loads(manifest.read_text())['files']
  for p,digest in f.items():assert sha(frame/p)==digest,p
 cfg=json.loads(base.read_text());patch=json.loads((source/'future_config_patch_NOT_BOUND.json').read_text());cfg['physical_features']=patch['physical_features'];cfg['center_eligibility_2021_features']=patch['center_eligibility_2021_features'];cfg['derived_features']=cfg.get('derived_features',[])+patch['derived_features_additions'];cfg['cycle05_variant']='source_geography_inclusive';cfg['target_run_id']='sgrt_cycle06_access_v2__source_geography_inclusive';cfg['travel_edges']=cfg['travel_manifest']=rel(matrix)
 sources=[review,sr,source/'preregistration.json',source/'freeze_manifest.json',pre/'receipt.json',pre/'freeze_manifest.json',net/'artifact_manifest.json',route,net/'protocol.json',net/'source_scope_and_preservation_receipt.json',net/'budget_boundary_readback_receipt.json']
 out.mkdir(parents=True);protocol=out/'seventh_source_and_transport_binding_protocol.json';dump(protocol,dict(status='ACCEPTED_SEVENTH_CANONICAL_DISJOINT_UNION_AND_ALL7_TRANSPORT_BINDING_BEFORE_ACTUAL_CI',created_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),source_preregistration_sha256=sha(source/'preregistration.json'),source_preregistration_admission_sha256=sha(sr),transport_admission_sha256=sha(review),matrix_sha256=sha(matrix),snap_sha256=sha(snap),combined_all7_targets=17913,seventh_only_required_potential_targets=17491,first6_accepted_targets_preserved=6792,new_targets=11121,old_budget_upgrades=238,one_rejected_target_preserved=True,source_formats_and_baseline_eligibility_rules_unchanged=True,unknown_catalogue_absence_not_imputed_as_zero_function=True,old_six_configs_and_matrices_unchanged=True,primary_predictions_read=False,code_sha256=sha(Path(__file__))))
 cfg['provenance_sidecars']=list(dict.fromkeys(cfg['provenance_sidecars']+[rel(p) for p in sources]+[rel(protocol)]));shutil.copyfile(H/'cycle05_preregistration.json',out/'cycle05_preregistration.json')
 # Actual Mi and candidate identities must reproduce admitted source-only preflight.
 sys.path.insert(0,str(ROOT/'model'));import run_word_model_cycle05 as m
 nodes,watched=m.load_nodes(cfg);mass,components=m.build_mass(nodes,cfg);prior=pd.read_parquet(pre/'source_only_own_mass_components.parquet');assert prior.equals(mass),'Seventh bound source mass/candidates differ from preflight';fingerprint=hashlib.sha256(pd.util.hash_pandas_object(mass[['id','own_positive_mass']],index=False).to_numpy().tobytes()).hexdigest();assert fingerprint=='798cbd57ac83308e041f9dcbe71975121ac5e6f939dee5f279262d9a55b2c175' and int(mass.candidate_center.sum())==9329
 p=out/'config_source_geography_inclusive_provisional.json';dump(p,cfg);dump(out/'binding_receipt.json',dict(status='BOUND_SEVENTH_ACTUAL_MI_AND_CANDIDATES_EXACT_PREFLIGHT_EQUAL',config=rel(p),configuration_sha256=sha(p),ownMi_values_sha256=fingerprint,candidate_centers=9329,all_mass_columns_and_candidates_exact_equal=True,matrix_sha256=sha(matrix),source_admission_sha256=sha(sr),transport_admission_sha256=sha(review),source_labels_or_primary_predictions_read=False,provisional_Ci_not_yet_run=True));files=list(out.iterdir());dump(out/'freeze_manifest.json',dict(files={p.name:sha(p) for p in files if p.is_file()}));print((out/'binding_receipt.json').read_text())
